import { randomUUID } from "node:crypto";

// Amplop yang sama untuk semua pesan. `type` + `version` menentukan
// routing key (mis. "stock.reserved.v1") dan skema `data`.
export type Envelope<T = Record<string, unknown>> = {
  id: string;             // kunci dedup, unik per pesan
  type: string;           // "inventory.reserve" (perintah) / "stock.reserved" (fakta)
  version: number;        // naik hanya untuk perubahan yang merusak
  occurred_at: string;    // ISO 8601
  source: string;         // layanan pengirim
  correlation_id: string; // id pesanan, mengikat semua pesan satu saga
  data: T;
};

export function envelope<T extends Record<string, unknown>>(
  type: string, version: number, correlationId: string, data: T,
): Envelope<T> {
  return {
    id: randomUUID(),
    type,
    version,
    occurred_at: new Date().toISOString(),
    source: process.env.SERVICE ?? "unknown",
    correlation_id: correlationId,
    data,
  };
}

export const routingKey = (e: Envelope) => `${e.type}.v${e.version}`;

