import pg from "pg";

// Ukuran pool minimal sama dengan prefetch konsumen + koneksi HTTP + relay.
export const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL,
  max: Number(process.env.PG_POOL_MAX ?? 30),
});

export async function tx<T>(fn: (c: pg.PoolClient) => Promise<T>): Promise<T> {
  const c = await pool.connect();
  try {
    await c.query("BEGIN");
    const result = await fn(c);
    await c.query("COMMIT");
    return result;
  } catch (err) {
    await c.query("ROLLBACK");
    throw err;
  } finally {
    c.release();
  }
}

import { ROOT_CONTEXT, context, propagation } from "@opentelemetry/api";
import type pg from "pg";
import { tx } from "./db.ts";
import { routingKey, type Envelope } from "./envelope.ts";

export type OutboxRow = { routing_key: string; payload: Envelope; headers: Record<string, string> };
export type Publish = (rows: OutboxRow[]) => Promise<void>;

// Dipanggil DI DALAM transaksi bisnis. Konteks trace aktif ikut disimpan
// supaya trace tidak putus saat event baru terbit beberapa ms kemudian.
export async function addToOutbox(c: pg.PoolClient, e: Envelope): Promise<void> {
  const headers: Record<string, string> = {};
  propagation.inject(context.active(), headers);
  await c.query(
    "INSERT INTO outbox (event_id, routing_key, payload, headers) VALUES ($1, $2, $3, $4)",
    [e.id, routingKey(e), e, headers],
  );
}

// Satu putaran relay. FOR UPDATE SKIP LOCKED membuat dua relay tidak
// mengambil baris yang sama. Kalau publish gagal, transaksi di-rollback
// dan baris diambil lagi di putaran berikutnya: at-least-once, maka
// konsumen WAJIB idempoten.
export async function relayOnce(publish: Publish, batch = 200): Promise<number> {
  return tx(async (c) => {
    const { rows } = await c.query<OutboxRow & { id: string }>(
      `SELECT id, routing_key, payload, headers FROM outbox
        WHERE published_at IS NULL
        ORDER BY id
        LIMIT $1
        FOR UPDATE SKIP LOCKED`,
      [batch],
    );
    if (rows.length === 0) return 0;
    await publish(rows);
    await c.query("UPDATE outbox SET published_at = now() WHERE id = ANY($1)", [rows.map((r) => r.id)]);
    return rows.length;
  });
}

export async function runRelay(publish: Publish, signal?: AbortSignal): Promise<void> {
  while (!signal?.aborted) {
    const n = await relayOnce(publish).catch((err) => {
      console.error("relay gagal, dicoba lagi", err);
      return 0;
    });
    if (n === 0) await new Promise((r) => setTimeout(r, 100));
  }
}

// Jalankan fn di dalam konteks trace yang tersimpan di baris outbox.
export const withStoredContext = <T>(headers: Record<string, string>, fn: () => T): T =>
  context.with(propagation.extract(ROOT_CONTEXT, headers), fn);

import amqp, { type ConfirmChannel } from "amqplib";
import { withStoredContext, type Publish } from "./outbox.ts";

export const EXCHANGE = "flashsale";              // topic, semua perintah & event
export const DLX = "flashsale.dlx";               // tujuan pesan yang menyerah
export const RETRY_DELAYS_MS = [1_000, 5_000, 25_000];

export async function connectBroker(): Promise<ConfirmChannel> {
  const conn = await amqp.connect(process.env.AMQP_URL ?? "amqp://localhost");
  // ponytail: crash-only. Proses mati saat koneksi putus dan Docker
  // menyalakannya lagi; pakai opsi `recovery` amqplib kalau restart terlalu mahal.
  conn.on("close", () => {
    console.error("koneksi AMQP putus, keluar");
    process.exit(1);
  });
  const ch = await conn.createConfirmChannel();
  await ch.assertExchange(EXCHANGE, "topic", { durable: true });
  await ch.assertExchange(DLX, "direct", { durable: true });
  return ch;
}

// Antrean utama (quorum) + antrean retry per jeda + DLQ untuk satu konsumen.
export async function declareQueue(ch: ConfirmChannel, queue: string, routingKeys: string[]) {
  await ch.assertQueue(queue, {
    durable: true,
    arguments: {
      "x-queue-type": "quorum",
      "x-delivery-limit": 10,            // proses crash berulang -> DLQ, bukan loop abadi
      "x-dead-letter-exchange": DLX,
      "x-dead-letter-routing-key": queue,
    },
  });
  for (const key of routingKeys) await ch.bindQueue(queue, EXCHANGE, key);

  await ch.assertQueue(`${queue}.dlq`, { durable: true });
  await ch.bindQueue(`${queue}.dlq`, DLX, queue);

  // Satu antrean per jeda: TTL seragam, jadi tidak ada pesan yang
  // tertahan di belakang pesan ber-TTL lebih panjang. Setelah TTL habis,
  // pesan dikembalikan ke antrean utama lewat default exchange.
  for (const ms of RETRY_DELAYS_MS) {
    await ch.assertQueue(`${queue}.retry.${ms}`, {
      durable: true,
      arguments: {
        "x-message-ttl": ms,
        "x-dead-letter-exchange": "",
        "x-dead-letter-routing-key": queue,
      },
    });
  }
}

export function publisher(ch: ConfirmChannel): Publish {
  return async (rows) => {
    for (const r of rows) {
      withStoredContext(r.headers, () =>
        ch.publish(EXCHANGE, r.routing_key, Buffer.from(JSON.stringify(r.payload)), {
          persistent: true,
          contentType: "application/json",
          messageId: r.payload.id,
          headers: { ...r.headers },
        }),
      );
    }
    await ch.waitForConfirms(); // baru dianggap terbit setelah broker mengonfirmasi
  };
}

import type { ConfirmChannel, ConsumeMessage } from "amqplib";
import type pg from "pg";
import { RETRY_DELAYS_MS, declareQueue } from "./broker.ts";
import { tx } from "./db.ts";
import { routingKey, type Envelope } from "./envelope.ts";

export type Handler = (c: pg.PoolClient, e: Envelope) => Promise<void>;

// Error yang tidak akan sembuh dengan dicoba ulang (data rusak, tipe
// tak dikenal). Langsung ke DLQ.
export class PermanentError extends Error {}

// Inti idempotensi: catat event_id dan jalankan efek samping di SATU
// transaksi. Duplikat yang datang bersamaan akan menunggu kunci baris
// primary key, lalu melihat konflik dan berhenti.
export async function handleOnce(consumer: string, e: Envelope, handler: Handler): Promise<boolean> {
  return tx(async (c) => {
    const { rowCount } = await c.query(
      "INSERT INTO processed_events (consumer, event_id) VALUES ($1, $2) ON CONFLICT DO NOTHING",
      [consumer, e.id],
    );
    if (rowCount === 0) return false; // sudah pernah diproses
    await handler(c, e);
    return true;
  });
}

export async function consume(ch: ConfirmChannel, queue: string, handlers: Record<string, Handler>) {
  await declareQueue(ch, queue, Object.keys(handlers));
  await ch.prefetch(Number(process.env.PREFETCH ?? 20));

  await ch.consume(queue, async (msg: ConsumeMessage | null) => {
    if (!msg) return; // konsumen dibatalkan broker
    try {
      let e: Envelope;
      try {
        e = JSON.parse(msg.content.toString());
      } catch {
        throw new PermanentError("body bukan JSON");
      }
      // Jangan pakai msg.fields.routingKey: setelah retry nilainya nama antrean.
      const handler = handlers[routingKey(e)];
      if (!handler) throw new PermanentError(`tidak ada handler untuk ${routingKey(e)}`);
      await handleOnce(queue, e, handler);
      ch.ack(msg);
    } catch (err) {
      await retryOrDeadLetter(ch, queue, msg, err);
    }
  });
}

async function retryOrDeadLetter(ch: ConfirmChannel, queue: string, msg: ConsumeMessage, err: unknown) {
  const attempt = Number(msg.properties.headers?.["x-attempt"] ?? 0);
  const giveUp = err instanceof PermanentError || attempt >= RETRY_DELAYS_MS.length;
  const target = giveUp ? `${queue}.dlq` : `${queue}.retry.${RETRY_DELAYS_MS[attempt]}`;
  console.error(`[${queue}] gagal (percobaan ${attempt + 1}) -> ${target}:`, err);

  ch.sendToQueue(target, msg.content, {
    persistent: true,
    contentType: msg.properties.contentType,
    messageId: msg.properties.messageId,
    headers: { ...msg.properties.headers, "x-attempt": attempt + 1, "x-last-error": String(err).slice(0, 500) },
  });
  await ch.waitForConfirms(); // salinan aman dulu, baru yang asli di-ack
  ch.ack(msg);
}

import type pg from "pg";

export type ReserveResult = "reserved" | "rejected";

// Reservasi stok yang aman dari oversell dan aman diulang.
// 1. Klaim slot reservasi per pesanan. Kalau sudah ada, kembalikan hasil
//    lama: perintah yang terkirim dua kali tidak memotong stok dua kali.
// 2. Kurangi stok secara atomik. Kondisi `available >= $2` dievaluasi
//    ulang oleh Postgres setelah menunggu kunci baris, jadi transaksi
//    yang kalah antre melihat angka terbaru, bukan angka basi.
export async function reserve(c: pg.PoolClient, orderId: string, sku: string, qty: number): Promise<ReserveResult> {
  const claimed = await c.query(
    `INSERT INTO reservations (order_id, sku, qty, status) VALUES ($1, $2, $3, 'held')
     ON CONFLICT (order_id) DO NOTHING`,
    [orderId, sku, qty],
  );
  if (claimed.rowCount === 0) {
    const { rows } = await c.query("SELECT status FROM reservations WHERE order_id = $1", [orderId]);
    return rows[0].status === "rejected" ? "rejected" : "reserved";
  }

  const taken = await c.query(
    "UPDATE stock SET available = available - $2 WHERE sku = $1 AND available >= $2",
    [sku, qty],
  );
  if (taken.rowCount === 1) return "reserved";

  await c.query(
    "UPDATE reservations SET status = 'rejected', updated_at = now() WHERE order_id = $1",
    [orderId],
  );
  return "rejected";
}

// Kompensasi. Hanya reservasi berstatus 'held' yang dikembalikan, jadi
// perintah release yang datang dua kali tidak menambah stok dua kali.
export async function release(c: pg.PoolClient, orderId: string): Promise<boolean> {
  const { rows } = await c.query<{ sku: string; qty: number }>(
    `UPDATE reservations SET status = 'released', updated_at = now()
      WHERE order_id = $1 AND status = 'held'
      RETURNING sku, qty`,
    [orderId],
  );
  if (rows.length === 0) return false;
  await c.query("UPDATE stock SET available = available + $2 WHERE sku = $1", [rows[0].sku, rows[0].qty]);
  return true;
}

export async function commit(c: pg.PoolClient, orderId: string): Promise<void> {
  await c.query(
    "UPDATE reservations SET status = 'committed', updated_at = now() WHERE order_id = $1 AND status = 'held'",
    [orderId],
  );
}

import type { Handler } from "../shared/consumer.ts";
import { envelope } from "../shared/envelope.ts";
import { addToOutbox } from "../shared/outbox.ts";
import { commit, release, reserve } from "./stock.ts";

type ReserveCmd = { order_id: string; sku: string; qty: number };

export const inventoryHandlers: Record<string, Handler> = {
  "inventory.reserve.v1": async (c, e) => {
    const d = e.data as ReserveCmd;
    const result = await reserve(c, d.order_id, d.sku, d.qty);
    const reply = result === "reserved"
      ? envelope("stock.reserved", 1, d.order_id, { order_id: d.order_id, sku: d.sku, qty: d.qty })
      : envelope("stock.rejected", 1, d.order_id, { order_id: d.order_id, sku: d.sku, reason: "out_of_stock" });
    await addToOutbox(c, reply);
  },

  "inventory.release.v1": async (c, e) => {
    const orderId = (e.data as { order_id: string }).order_id;
    await release(c, orderId);
    // Tetap balas walau tidak ada yang dilepas, supaya saga bisa selesai.
    await addToOutbox(c, envelope("stock.released", 1, orderId, { order_id: orderId }));
  },

  "order.confirmed.v1": async (c, e) => {
    await commit(c, (e.data as { order_id: string }).order_id);
  },
};

