import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import { after, beforeEach, test } from "node:test";
import { pool, tx } from "../src/shared/db.ts";
import { release, reserve } from "../src/inventory/stock.ts";

const SKU = "TEST-OVERSELL";
const STOCK = 100;
const BUYERS = 500;

beforeEach(async () => {
  await pool.query("DELETE FROM reservations WHERE sku = $1", [SKU]);
  await pool.query(
    `INSERT INTO stock VALUES ($1, $2) ON CONFLICT (sku) DO UPDATE SET available = $2`,
    [SKU, STOCK],
  );
});
after(() => pool.end());

test(`${BUYERS} pembeli berebut ${STOCK} stok: tepat ${STOCK} yang menang`, async () => {
  const results = await Promise.all(
    Array.from({ length: BUYERS }, () => tx((c) => reserve(c, randomUUID(), SKU, 1))),
  );
  assert.equal(results.filter((r) => r === "reserved").length, STOCK);

  const { rows } = await pool.query(
    `SELECT s.available,
            (SELECT count(*)::int FROM reservations r WHERE r.sku = s.sku AND r.status = 'held') AS held
       FROM stock s WHERE s.sku = $1`,
    [SKU],
  );
  assert.deepEqual(rows[0], { available: 0, held: STOCK });
});

test("perintah reserve dan release yang terkirim dua kali tidak menggandakan efek", async () => {
  const orderId = randomUUID();
  const twice = await Promise.all([1, 2].map(() => tx((c) => reserve(c, orderId, SKU, 2))));
  assert.deepEqual(twice, ["reserved", "reserved"]);

  const released = await Promise.all([1, 2].map(() => tx((c) => release(c, orderId))));
  assert.deepEqual(released.sort(), [false, true]);

  const { rows } = await pool.query("SELECT available FROM stock WHERE sku = $1", [SKU]);
  assert.equal(rows[0].available, STOCK);
});

import type pg from "pg";
import type { Handler } from "../shared/consumer.ts";
import { tx } from "../shared/db.ts";
import { envelope } from "../shared/envelope.ts";
import { addToOutbox } from "../shared/outbox.ts";

type Status = "PENDING" | "AWAITING_PAYMENT" | "COMPENSATING" | "CONFIRMED" | "CANCELLED";
type Order = { id: string; amount: string; status: Status };

const PAYMENT_TIMEOUT = process.env.PAYMENT_TIMEOUT ?? "2 minutes";

// Satu-satunya cara mengubah status. Transisi hanya terjadi kalau status
// sekarang = `from`, jadi event duplikat, basi, atau datang tidak urut
// tidak bisa memundurkan saga. undefined = transisi ditolak.
async function move(c: pg.PoolClient, orderId: string, from: Status, to: Status, reason?: string) {
  const { rows } = await c.query<Order>(
    `UPDATE orders
        SET status = $3,
            cancel_reason = coalesce($4, cancel_reason),
            deadline_at = CASE WHEN $3 = 'AWAITING_PAYMENT' THEN now() + $5::interval END,
            updated_at = now()
      WHERE id = $1 AND status = $2
      RETURNING id, amount, status`,
    [orderId, from, to, reason ?? null, PAYMENT_TIMEOUT],
  );
  return rows[0];
}

async function compensate(c: pg.PoolClient, orderId: string, reason: string) {
  const o = await move(c, orderId, "AWAITING_PAYMENT", "COMPENSATING", reason);
  if (o) await addToOutbox(c, envelope("inventory.release", 1, o.id, { order_id: o.id }));
}

const orderIdOf = (data: unknown) => (data as { order_id: string }).order_id;

export const sagaHandlers: Record<string, Handler> = {
  "stock.reserved.v1": async (c, e) => {
    const o = await move(c, orderIdOf(e.data), "PENDING", "AWAITING_PAYMENT");
    if (o) await addToOutbox(c, envelope("payment.charge", 1, o.id, { order_id: o.id, amount: Number(o.amount) }));
  },

  "stock.rejected.v1": async (c, e) => {
    const o = await move(c, orderIdOf(e.data), "PENDING", "CANCELLED", "out_of_stock");
    if (o) await addToOutbox(c, envelope("order.cancelled", 1, o.id, { order_id: o.id, reason: "out_of_stock" }));
  },

  "payment.succeeded.v1": async (c, e) => {
    const id = orderIdOf(e.data);
    const o = await move(c, id, "AWAITING_PAYMENT", "CONFIRMED");
    if (o) return addToOutbox(c, envelope("order.confirmed", 1, id, { order_id: id }));
    // Pembayaran sukses SETELAH saga menyerah (timeout): uang harus kembali.
    const { rows } = await c.query("SELECT status FROM orders WHERE id = $1", [id]);
    if (rows[0]?.status === "COMPENSATING" || rows[0]?.status === "CANCELLED") {
      await addToOutbox(c, envelope("payment.refund", 1, id, { order_id: id }));
    }
  },

  "payment.failed.v1": async (c, e) => {
    await compensate(c, orderIdOf(e.data), "payment_failed");
  },

  "stock.released.v1": async (c, e) => {
    const o = await move(c, orderIdOf(e.data), "COMPENSATING", "CANCELLED");
    if (o) await addToOutbox(c, envelope("order.cancelled", 1, o.id, { order_id: o.id, reason: "payment_failed" }));
  },
};

// Pembayaran yang tidak dibalas sampai tenggat dianggap gagal.
export async function expireStuckOrders(): Promise<void> {
  await tx(async (c) => {
    const { rows } = await c.query<{ id: string }>(
      `SELECT id FROM orders
        WHERE status = 'AWAITING_PAYMENT' AND deadline_at < now()
        ORDER BY deadline_at LIMIT 100
        FOR UPDATE SKIP LOCKED`,
    );
    for (const r of rows) await compensate(c, r.id, "payment_timeout");
  });
}

import { randomUUID } from "node:crypto";
import type { IncomingMessage, ServerResponse } from "node:http";
import { pool, tx } from "../shared/db.ts";
import { envelope } from "../shared/envelope.ts";
import { addToOutbox } from "../shared/outbox.ts";

const send = (res: ServerResponse, status: number, body: unknown) => {
  res.writeHead(status, { "content-type": "application/json" }).end(JSON.stringify(body));
};

async function readJson(req: IncomingMessage): Promise<Record<string, unknown> | null> {
  let raw = "";
  for await (const chunk of req) {
    raw += chunk;
    if (raw.length > 4096) return null;
  }
  try {
    const v = JSON.parse(raw);
    return v && typeof v === "object" ? v : null;
  } catch {
    return null;
  }
}

export async function handle(req: IncomingMessage, res: ServerResponse) {
  const url = new URL(req.url ?? "/", "http://x");

  if (req.method === "GET" && url.pathname === "/healthz") return send(res, 200, { ok: true });

  const m = url.pathname.match(/^\/orders\/([0-9a-f-]{36})$/);
  if (req.method === "GET" && m) {
    const { rows } = await pool.query(
      "SELECT id, sku, qty, amount, status, cancel_reason FROM orders WHERE id = $1", [m[1]]);
    return rows[0] ? send(res, 200, rows[0]) : send(res, 404, { error: "pesanan tidak ditemukan" });
  }

  if (req.method === "POST" && url.pathname === "/orders") {
    const key = req.headers["idempotency-key"];
    const body = await readJson(req);
    const qty = Number(body?.qty);
    if (typeof key !== "string" || key.length < 8 || key.length > 100) {
      return send(res, 400, { error: "header Idempotency-Key wajib (8-100 karakter)" });
    }
    if (!body || typeof body.sku !== "string" || typeof body.user_id !== "string" || !Number.isInteger(qty) || qty < 1 || qty > 2) {
      return send(res, 400, { error: "body harus {sku, user_id, qty 1-2}" });
    }

    const order = await tx(async (c) => {
      const id = randomUUID();
      const { rows } = await c.query(
        `INSERT INTO orders (id, idempotency_key, user_id, sku, qty, amount)
         SELECT $1, $2, $3, sku, $5::int, price * $5::int FROM flash_items WHERE sku = $4
         ON CONFLICT (idempotency_key) DO NOTHING
         RETURNING id, status`,
        [id, key, body.user_id, body.sku, qty],
      );
      if (rows[0]) {
        await addToOutbox(c, envelope("inventory.reserve", 1, id, { order_id: id, sku: body.sku as string, qty }));
        return rows[0];
      }
      // Klien mengulang request (mis. timeout di jaringan): kembalikan pesanan lama.
      const prev = await c.query("SELECT id, status FROM orders WHERE idempotency_key = $1", [key]);
      return prev.rows[0]; // undefined kalau sku tidak ada di flash_items
    });
    return order ? send(res, 202, order) : send(res, 404, { error: "produk tidak ada di flash sale" });
  }

  send(res, 404, { error: "rute tidak ada" });
}

