import type { Handler } from "../shared/consumer.ts";
import { envelope } from "../shared/envelope.ts";
import { addToOutbox } from "../shared/outbox.ts";

// Gateway palsu. Di dunia nyata panggilan ini ke luar dan WAJIB membawa
// kunci idempotensi (di sini order_id) supaya retry tidak menagih dua kali.
const FAIL_RATE = Number(process.env.PAYMENT_FAIL_RATE ?? 0.2);
const fakeGateway = async (_orderId: string, _amount: number) => Math.random() >= FAIL_RATE;

type Charge = { order_id: string; amount: number };

export const paymentHandlers: Record<string, Handler> = {
  "payment.charge.v1": async (c, e) => {
    const d = e.data as Charge;
    const existing = await c.query("SELECT status FROM payments WHERE order_id = $1", [d.order_id]);
    // ponytail: gateway dipanggil di dalam transaksi DB; untuk gateway lambat,
    // pisahkan jadi status 'pending' + transaksi kedua.
    const ok = existing.rows[0] ? existing.rows[0].status !== "failed" : await fakeGateway(d.order_id, d.amount);
    if (!existing.rows[0]) {
      await c.query("INSERT INTO payments (order_id, amount, status) VALUES ($1, $2, $3)",
        [d.order_id, d.amount, ok ? "succeeded" : "failed"]);
    }
    await addToOutbox(c, ok
      ? envelope("payment.succeeded", 1, d.order_id, { order_id: d.order_id, amount: d.amount })
      : envelope("payment.failed", 1, d.order_id, { order_id: d.order_id, reason: "declined" }));
  },

  "payment.refund.v1": async (c, e) => {
    const orderId = (e.data as { order_id: string }).order_id;
    const { rowCount } = await c.query(
      "UPDATE payments SET status = 'refunded' WHERE order_id = $1 AND status = 'succeeded'", [orderId]);
    if (rowCount) await addToOutbox(c, envelope("payment.refunded", 1, orderId, { order_id: orderId }));
  },
};

