}

// Gagal kalau pesan tidak punya skema (katalog bolong) atau tidak cocok.
export function assertContract(e: Envelope): void {
  const id = `https://contracts.flashsale.local/${routingKey(e)}.schema.json`;
  const validate = ajv.getSchema(id);
  assert.ok(validate, `tidak ada kontrak untuk ${routingKey(e)}`);
  assert.ok(validate(e), `${routingKey(e)} melanggar kontrak: ${ajv.errorsText(validate.errors)}`);
}

export const examples = (): Envelope[] =>
  readdirSync(new URL("examples/", dir)).map((f) => JSON.parse(readFileSync(new URL(`examples/${f}`, dir), "utf8")));

