async function newOrder() {
  const id = randomUUID();
  await pool.query(
    "INSERT INTO orders (id, idempotency_key, user_id, sku, qty, amount) VALUES ($1, $2, 'u1', 'FLASH-001', 1, 99000)",
    [id, `test-${id}`]);
  return id;
}
const deliver = (e: Envelope) => handleOnce("order", e, sagaHandlers[routingKey(e)]);
const reply = (type: string, id: string, extra: Record<string, unknown> = {}) =>
  envelope(type, 1, id, { order_id: id, ...extra });

async function status(id: string) {
  const { rows } = await pool.query("SELECT status FROM orders WHERE id = $1", [id]);
  return rows[0].status;
}
// Semua yang diterbitkan order service harus lolos kontrak.
async function published(id: string): Promise<string[]> {
  const { rows } = await pool.query<{ payload: Envelope }>(
    "SELECT payload FROM outbox WHERE payload->>'correlation_id' = $1 ORDER BY id", [id]);
  rows.forEach((r) => assertContract(r.payload));
  return rows.map((r) => routingKey(r.payload));
}

