// Cek konsistensi akhir setelah uji beban / chaos drill.
//   PG=postgres://postgres:flash@localhost:5432 INITIAL_STOCK=100 node scripts/verify.ts
import pg from "pg";

const base = process.env.PG ?? "postgres://postgres:flash@localhost:5432";
const initial = Number(process.env.INITIAL_STOCK ?? 100);
const sku = process.env.SKU ?? "FLASH-001";
const db = (name: string) => new pg.Client(`${base}/${name}`);
const [order, inventory, payment] = [db("order_db"), db("inventory_db"), db("payment_db")];
await Promise.all([order, inventory, payment].map((c) => c.connect()));

const one = async (c: pg.Client, sql: string, params: unknown[] = []) => (await c.query(sql, params)).rows[0];

const o = await one(order, `
  SELECT count(*) FILTER (WHERE status NOT IN ('CONFIRMED','CANCELLED'))::int AS in_flight,
         coalesce(sum(qty) FILTER (WHERE status = 'CONFIRMED'), 0)::int      AS confirmed_qty,
         count(*) FILTER (WHERE status = 'CONFIRMED')::int                    AS confirmed
    FROM orders WHERE sku = $1`, [sku]);
const i = await one(inventory, `
  SELECT s.available,
         coalesce(sum(r.qty) FILTER (WHERE r.status = 'held'), 0)::int      AS held,
         coalesce(sum(r.qty) FILTER (WHERE r.status = 'committed'), 0)::int AS committed
    FROM stock s LEFT JOIN reservations r ON r.sku = s.sku
   WHERE s.sku = $1 GROUP BY s.available`, [sku]);
const p = await one(payment, `SELECT count(*) FILTER (WHERE status = 'succeeded')::int AS charged FROM payments`);
const outbox = await Promise.all([order, inventory, payment].map((c) =>
  one(c, "SELECT count(*)::int AS n FROM outbox WHERE published_at IS NULL")));

const checks: [string, boolean][] = [
  ["tidak ada pesanan yang menggantung", o.in_flight === 0],
  ["tidak ada stok yang masih ditahan", i.held === 0],
  ["stok terjual = stok terkonfirmasi", i.committed === o.confirmed_qty],
  ["tidak ada oversell: tersedia + terjual = stok awal", i.available + i.committed === initial],
  ["yang ditagih = yang terkonfirmasi (sisanya sudah refund)", p.charged === o.confirmed],
  ["semua outbox sudah terbit", outbox.every((r) => r.n === 0)],
];
console.table({ ...o, ...i, ...p, unpublished: outbox.map((r) => r.n).join("/") });
for (const [name, ok] of checks) console.log(ok ? "LULUS" : "GAGAL", name);
await Promise.all([order, inventory, payment].map((c) => c.end()));
process.exit(checks.every(([, ok]) => ok) ? 0 : 1);

